"use client";

import { FormEvent, type ReactNode, useCallback, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { api, clearSession } from "../../lib/api";

type Website = { id: string; url: string; normalized_url?: string; is_primary: boolean; last_scan_at?: string | null; robots_txt_found?: boolean | null; sitemap_found?: boolean | null; detected_cms?: string | null; monitoring_enabled?: boolean; monitor_frequency?: string; monitor_hour?: number; monitor_minute?: number; monitor_day_of_week?: number; monitor_timezone?: string; monitor_job_id?: string | null; last_monitor_run_at?: string | null };
type Business = { id: string; name: string; industry?: string | null; description?: string | null; location?: string | null; primary_website_url?: string | null; onboarding_step?: string | null; is_default?: boolean; is_onboarded: boolean; websites: Website[]; profile?: Profile | null };
type Profile = { products: string[]; services: string[]; unique_selling_points: string[]; target_audience?: string | null; audience_segments: string[]; service_areas: string[]; brand_voice?: string | null; brand_tone?: string | null; content_restrictions: string[]; preferred_reading_level?: string | null; keywords: string[]; social_links: Record<string,string>; contact_email?: string | null; contact_phone?: string | null; completeness_percent: number; missing_fields: string[] };
type Scan = { id: string; sequence?: number; trigger?: string; status: string; progress_percent: number; progress_message?: string | null; pages_discovered: number; pages_crawled: number; pages_failed: number; hit_page_limit?: boolean; completed_at?: string | null; duration_ms?: number | null; created_at?: string };
type SeoIssue = { id: string; rule_id: string; category: string; severity: string; title: string; description: string; suggested_fix?: string | null; points_deducted: number; page_url?: string | null; affected_page_count: number; evidence?: Record<string,unknown> };
type SeoReport = { overall_score: number; grade: string; pages_analyzed: number; issue_count: number; critical_count: number; high_count: number; medium_count: number; low_count: number; engine_version: string; summary?: string | null; categories?: { category:string; normalized_score:number; points_earned:number; points_available:number; weight:number; check_results?:Record<string,unknown> }[]; issues?: SeoIssue[] };
type AiReport = { overall_score:number; grade:string; pages_analyzed:number; engine_version:string; disclaimer:string; summary?:string|null; categories?:{category:string; normalized_score:number; points_earned:number; points_available:number; weight:number; signal_results?:Record<string,unknown>}[] };
type Recommendation = { id:string; title:string; description:string; suggested_action:string; severity:string; impact:string; effort:string; priority_score:number; priority_bucket:string; status:string; estimated_score_gain?:number|null; affected_page_count:number; example_urls?:string[]; evidence?:Record<string,unknown>; rule_id:string };
type RecommendationList = { items:Recommendation[]; summary:{total:number; open:number; by_status:Record<string,number>; by_bucket:Record<string,number>; estimated_total_gain:number} };
type Content = { id:string; content_type:string; status:string; source:string; title:string; body:string; excerpt?:string|null; meta_title?:string|null; meta_description?:string|null; target_keywords:string[]; generation_mode:string; ai_model?:string|null; word_count:number; latest_score?:number|null; current_version:number; edited_by_user:boolean; created_at:string; updated_at:string };
type ContentScore = { id:string; content_id:string; version_number:number; overall_score:number; grade:string; category_scores:Record<string, {earned:number;available:number;checks?:Record<string,unknown>}>; issues:Array<{rule_id:string;severity:string;title:string;description:string;points:number}>; suggestions:Array<{rule_id:string;severity:string;title:string;description:string}>; readability_score?:number|null; reading_grade_level?:number|null; keyword_density:Record<string,number>; engine_version:string; created_at:string };
type Opportunity = { id:string; title:string; suggested_content_type:string; description?:string|null; rationale:string; source:string; target_keywords:string[]; suggested_outline:string[]; impact:string; effort:string; priority_score:number; status:string; content_id?:string|null; created_at:string; updated_at:string };
type Connection = { id:string; platform:string; mode:string; status:string; account_name?:string|null; account_url?:string|null; target_identifier?:string|null; connected_at?:string|null; last_used_at?:string|null; last_error?:string|null; granted_scopes:string[]; platform_metadata:Record<string,unknown> };
type Post = { id:string; content_id:string; connection_id?:string|null; platform:string; mode:string; status:string; remote_post_id?:string|null; remote_url?:string|null; published_at?:string|null; request_payload:Record<string,unknown>; response_payload:Record<string,unknown>; error_code?:string|null; error_message?:string|null; attempt_count:number };
type ScheduledPost = { id:string; post_id:string; scheduled_for:string; timezone_name:string; status:string; job_id?:string|null; retry_count:number; max_retries:number; error_message?:string|null };
type Snapshot = { id:string; snapshot_date:string; platform?:string|null; total_reach:number; total_impressions:number; total_engagement:number; total_likes:number; total_comments:number; total_shares:number; total_clicks:number; posts_published:number; engagement_rate?:number|null; has_real_data:boolean; has_demo_data:boolean; source_breakdown:Record<string,number> };
type Improvement = { id:string; previous_scan_id:string; current_scan_id:string; previous_seo_score:number; current_seo_score:number; seo_delta:number; previous_ai_visibility_score:number; current_ai_visibility_score:number; ai_visibility_delta:number; recommendations_applied:number; applied_details:Array<Record<string,unknown>>; new_issues:Array<Record<string,unknown>>; issues_resolved:number; issues_introduced:number; category_deltas:Record<string,Record<string,{previous:number;current:number;delta:number}>>; is_comparable:boolean; incomparable_reason?:string|null; summary?:string|null; created_at:string };
type Notification = { id:string; title:string; message:string; level:string; is_read:boolean; created_at:string; business_id?:string|null };
type Activity = { id:string; action:string; description:string; created_at:string; business_id?:string|null };
type Capabilities = { environment:string; database:string; ai:{enabled:boolean;model?:string|null;required_credential?:string|null}; connectors:Record<string,{mode:string;required_credentials:string[]}>; scheduler:{enabled:boolean} };

type Section = "Overview"|"Websites & scans"|"Recommendations"|"Content Studio"|"Publishing"|"Analytics"|"Assistant"|"Improvements"|"Notifications"|"Settings";
const sections: Section[] = ["Overview","Websites & scans","Recommendations","Content Studio","Publishing","Analytics","Assistant","Improvements","Notifications","Settings"];

const scoreClass = (value:number) => value >= 85 ? "score-high" : value >= 70 ? "score-good" : value >= 50 ? "score-mid" : "score-low";
const pretty = (value:string) => value.replaceAll("_", " ").replace(/\b\w/g, c => c.toUpperCase());
const dateText = (value?:string|null) => value ? new Date(value).toLocaleString() : "-";
const compact = (value:number) => new Intl.NumberFormat("en", {notation:"compact", maximumFractionDigits:1}).format(value);

function Sparkline({ values, label }: { values:number[]; label:string }) {
  if (!values.length) return <div className="chart-empty">No trend data yet.</div>;
  const max = Math.max(...values); const min = Math.min(...values); const range = max - min || 1;
  const points = values.map((v, i) => `${(i/(Math.max(values.length-1,1)))*100},${100-((v-min)/range)*78-10}`).join(" ");
  return <div className="spark-wrap" aria-label={label}><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="spark"><polyline points={points} fill="none" stroke="currentColor" strokeWidth="2.4" vectorEffect="non-scaling-stroke" /></svg><div className="spark-meta"><span>{Math.round(values[values.length-1])}</span><span>{min === max ? "Stable" : `${Math.round(values[values.length-1]-values[0]) >= 0 ? "+" : ""}${Math.round(values[values.length-1]-values[0])}`}</span></div></div>;
}

function Modal({ title, children, onClose }: { title:string; children:ReactNode; onClose:()=>void }) {
  return <div className="modal-backdrop" role="dialog" aria-modal="true"><div className="modal"><div className="modal-head"><div><p className="eyebrow">AURA WORKSPACE</p><h2>{title}</h2></div><button className="icon-button" onClick={onClose} aria-label="Close">×</button></div>{children}</div></div>;
}

function Empty({ title, text, action, onClick }: { title:string; text:string; action?:string; onClick?:()=>void }) {
  return <div className="empty"><div className="empty-icon">✦</div><h3>{title}</h3><p>{text}</p>{action && onClick && <button className="button" onClick={onClick}>{action}</button>}</div>;
}

const badgeToneAliases: Record<string,string> = {
  crawling:"scoring", analyzing:"scoring", partial:"medium",
  poor:"low", quick_win:"excellent", major_project:"high", fill_in:"low", long_term:"medium",
  manual:"demo", publishing:"scoring", published:"completed", cancelled:"dismissed", sent:"completed",
  success:"completed", warning:"medium", error:"failed",
  draft:"pending", generating:"scoring", ready:"completed", archived:"dismissed",
  user_entered:"neutral", derived:"neutral", platform_api:"live",
};
const badgeTones = new Set(["completed","live","good","excellent","connected","pending","demo","queued","scheduled","medium","fair","failed","critical","low","dismissed","high","in_progress","scoring"]);
function Badge({ children, tone="neutral" }: { children:ReactNode; tone?:string }) {
  const mapped = badgeToneAliases[tone] ?? tone;
  return <span className={badgeTones.has(mapped) ? `badge badge-${mapped}` : "badge"}>{children}</span>;
}

const provenanceText = (s?: Snapshot|null) => {
  if (!s) return "No data yet";
  const keys = Object.keys(s.source_breakdown ?? {});
  if (keys.length) return keys.map(pretty).join(" · ");
  if (s.has_demo_data) return "Demo";
  if (s.has_real_data) return "Platform API";
  return "Derived";
};

export default function Dashboard() {
  const router = useRouter();
  const [section, setSection] = useState<Section>("Overview");
  const [businesses, setBusinesses] = useState<Business[]>([]);
  const [businessId, setBusinessId] = useState("");
  const [business, setBusiness] = useState<Business|null>(null);
  const [website, setWebsite] = useState<Website|null>(null);
  const [scan, setScan] = useState<Scan|null>(null);
  const [scans, setScans] = useState<Scan[]>([]);
  const [seo, setSeo] = useState<SeoReport|null>(null);
  const [ai, setAi] = useState<AiReport|null>(null);
  const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
  const [recSummary, setRecSummary] = useState<RecommendationList["summary"]|null>(null);
  const [content, setContent] = useState<Content[]>([]);
  const [opportunities, setOpportunities] = useState<Opportunity[]>([]);
  const [connections, setConnections] = useState<Connection[]>([]);
  const [posts, setPosts] = useState<Post[]>([]);
  const [scheduled, setScheduled] = useState<ScheduledPost[]>([]);
  const [snapshots, setSnapshots] = useState<Snapshot[]>([]);
  const [improvements, setImprovements] = useState<Improvement[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [activities, setActivities] = useState<Activity[]>([]);
  const [capabilities, setCapabilities] = useState<Capabilities|null>(null);
  const [historySeo, setHistorySeo] = useState<number[]>([]);
  const [historyAi, setHistoryAi] = useState<number[]>([]);
  const [loading, setLoading] = useState(true);
  const [working, setWorking] = useState(false);
  const [error, setError] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);
  const [modal, setModal] = useState<string|null>(null);
  const [name, setName] = useState(""); const [industry, setIndustry] = useState(""); const [siteUrl, setSiteUrl] = useState("");
  const [profileForm, setProfileForm] = useState({ target_audience:"", brand_voice:"", brand_tone:"", keywords:"", products:"", services:"" });
  const [generateForm, setGenerateForm] = useState({ content_type:"blog_article", topic:"", tone:"clear", target_keywords:"", audience:"", call_to_action:"" });
  const [selectedOpportunity, setSelectedOpportunity] = useState<Opportunity|null>(null);
  const [demoMetricForm, setDemoMetricForm] = useState({ post_id:"", measured_on:new Date().toISOString().slice(0,10), reach:"", impressions:"", engagement:"", likes:"", comments:"", shares:"", clicks:"" });
  const [editingContent, setEditingContent] = useState<Content|null>(null);
  const [schedulingContent, setSchedulingContent] = useState<Content|null>(null);
  const [selectedContentScore, setSelectedContentScore] = useState<ContentScore|null>(null);
  const [newConnection, setNewConnection] = useState({platform:"wordpress",account_name:"",access_token:"",account_url:"",target_identifier:""});
  const [chat, setChat] = useState(""); const [messages, setMessages] = useState<{role:string;content:string}[]>([]);
  const [improvePrev, setImprovePrev] = useState(""); const [improveCurrent, setImproveCurrent] = useState("");
  const [monitorForm, setMonitorForm] = useState({ enabled:false, frequency:"weekly", hour:9, minute:0, day_of_week:0, timezone:"UTC" });

  const showError = (e:unknown) => setError(e instanceof Error ? e.message : "Something went wrong");

  const loadBusinesses = useCallback(async () => {
    const list = await api<Business[]>("/businesses");
    setBusinesses(list);
    const selected = list.find(b => b.id === businessId) ?? list.find(b => b.is_default) ?? list[0];
    if (selected && selected.id !== businessId) setBusinessId(selected.id);
    return selected;
  }, [businessId]);

  const loadHistory = useCallback(async (id:string, site:Website) => {
    try {
      const history = await api<Scan[]>(`/businesses/${id}/websites/${site.id}/scans`);
      const done = history.filter(s => ["completed","partial"].includes(s.status)).slice(0,8).reverse();
      const reports = await Promise.all(done.map(async s => {
        const [seoR, aiR] = await Promise.all([
          api<SeoReport>(`/businesses/${id}/websites/${site.id}/scans/${s.id}/seo`).catch(()=>null),
          api<AiReport>(`/businesses/${id}/websites/${site.id}/scans/${s.id}/ai-visibility`).catch(()=>null),
        ]); return {seo:seoR?.overall_score ?? null, ai:aiR?.overall_score ?? null};
      }));
      setHistorySeo(reports.map(r=>r.seo).filter((v): v is number => v !== null));
      setHistoryAi(reports.map(r=>r.ai).filter((v): v is number => v !== null));
    } catch { /* trend is optional */ }
  }, []);

  const loadWorkspace = useCallback(async (id:string = businessId) => {
    if (!id) return;
    setLoading(true); setError("");
    try {
      const detail = await api<Business>(`/businesses/${id}`);
      setBusiness(detail); setBusinesses(items => items.map(b=>b.id===id?detail:b));
      const site = detail.websites.find(w=>w.is_primary) ?? detail.websites[0] ?? null;
      setWebsite(site);
      if (site) setMonitorForm({enabled:site.monitoring_enabled ?? false, frequency:site.monitor_frequency ?? "weekly", hour:site.monitor_hour ?? 9, minute:site.monitor_minute ?? 0, day_of_week:site.monitor_day_of_week ?? 0, timezone:site.monitor_timezone ?? Intl.DateTimeFormat().resolvedOptions().timeZone});
      const recResult = await api<RecommendationList>(`/businesses/${id}/recommendations`);
      setRecommendations(recResult.items); setRecSummary(recResult.summary);
      const contentResult = await api<{items:Content[];total:number}>(`/businesses/${id}/content`);
      setContent(contentResult.items);
      const opp = await api<Opportunity[]>(`/businesses/${id}/opportunities`).catch(()=>[]);
      setOpportunities(opp);
      const conn = await api<Connection[]>(`/businesses/${id}/publishing/connections`).catch(()=>[]); setConnections(conn);
      setPosts(await api<Post[]>(`/businesses/${id}/publishing/posts`).catch(()=>[]));
      setScheduled(await api<ScheduledPost[]>(`/businesses/${id}/publishing/scheduled`).catch(()=>[]));
      setSnapshots(await api<Snapshot[]>(`/businesses/${id}/analytics/snapshots`).catch(()=>[]));
      setImprovements(site ? await api<Improvement[]>(`/businesses/${id}/websites/${site.id}/improvements`).catch(()=>[]) : []);
      setNotifications((await api<{items:Notification[]}>(`/notifications?business_id=${id}`).catch(()=>({items:[]}))).items);
      setActivities((await api<{items:Activity[]}>(`/activity?business_id=${id}`).catch(()=>({items:[]}))).items);
      setCapabilities(await api<Capabilities>("/meta/capabilities").catch(()=>null));
      if (site) {
        const latest = await api<Scan>(`/businesses/${id}/websites/${site.id}/scans/latest`).catch(()=>null);
        setScan(latest);
        if (latest) {
          const [seoR, aiR] = await Promise.all([
            api<SeoReport>(`/businesses/${id}/websites/${site.id}/scans/${latest.id}/seo`).catch(()=>null),
            api<AiReport>(`/businesses/${id}/websites/${site.id}/scans/${latest.id}/ai-visibility`).catch(()=>null),
          ]);
          setSeo(seoR); setAi(aiR);
          await loadHistory(id, site);
        } else { setSeo(null); setAi(null); setScans([]); }
        const allScans = await api<Scan[]>(`/businesses/${id}/websites/${site.id}/scans`).catch(()=>[]); setScans(allScans);
      } else { setScan(null); setSeo(null); setAi(null); setScans([]); setHistorySeo([]); setHistoryAi([]); }
      if (detail.profile) setProfileForm({target_audience:detail.profile.target_audience ?? "", brand_voice:detail.profile.brand_voice ?? "", brand_tone:detail.profile.brand_tone ?? "", keywords:detail.profile.keywords.join(", "), products:detail.profile.products.join(", "), services:detail.profile.services.join(", ")});
    } catch (e) { showError(e); }
    finally { setLoading(false); }
  }, [businessId, loadHistory]);

  useEffect(() => { if (!localStorage.getItem("aura_access_token")) router.replace("/login"); else loadBusinesses().catch(showError).finally(()=>setLoading(false)); }, [loadBusinesses, router]);
  useEffect(() => { if (businessId) loadWorkspace(businessId); }, [businessId, loadWorkspace]);
  useEffect(() => { if (scan && !["completed","partial","failed"].includes(scan.status)) { const t=setTimeout(()=>loadWorkspace(), 2500); return ()=>clearTimeout(t); } }, [scan, loadWorkspace]);

  const startScan = async () => { if (!website) { setModal("site"); return; } setWorking(true); setError(""); try { const created=await api<Scan>(`/businesses/${businessId}/websites/${website.id}/scans`,{method:"POST"}); setScan(created); setSection("Websites & scans"); } catch(e){showError(e);} finally{setWorking(false);} };
  const updateMonitoring = async (nextForm = monitorForm) => { if (!website) return; setWorking(true); try { const updated=await api<Website>(`/businesses/${businessId}/websites/${website.id}/monitoring`,{method:"PATCH",body:JSON.stringify(nextForm)}); setMonitorForm({enabled:updated.monitoring_enabled ?? false,frequency:updated.monitor_frequency ?? "weekly",hour:updated.monitor_hour ?? 9,minute:updated.monitor_minute ?? 0,day_of_week:updated.monitor_day_of_week ?? 0,timezone:updated.monitor_timezone ?? "UTC"}); setWebsite(updated); setBusinesses(items=>items.map(item=>item.id===businessId?{...item,websites:item.websites.map(site=>site.id===updated.id?updated:site)}:item)); } catch(e){showError(e)} finally{setWorking(false)} };
  const createBusiness = async (e:FormEvent) => { e.preventDefault(); setWorking(true); try { const created=await api<Business>("/businesses",{method:"POST",body:JSON.stringify({name,industry:industry||null})}); setBusinesses(b=>[...b,created]); setBusinessId(created.id); setModal(null); setName("");setIndustry(""); }catch(e){showError(e)}finally{setWorking(false)} };
  const addWebsite = async (e:FormEvent) => { e.preventDefault(); setWorking(true); try { await api(`/businesses/${businessId}/websites`,{method:"POST",body:JSON.stringify({url:siteUrl,is_primary:!business?.websites?.length})}); setSiteUrl("");setModal(null);await loadWorkspace(); }catch(e){showError(e)}finally{setWorking(false)} };
  const updateRec = async (id:string,status:string) => { try { await api(`/businesses/${businessId}/recommendations/${id}`,{method:"PATCH",body:JSON.stringify({status})}); await loadWorkspace(); }catch(e){showError(e)} };
  const regenerateRecs = async () => { setWorking(true); try { await api(`/businesses/${businessId}/recommendations/regenerate`,{method:"POST"}); await loadWorkspace(); }catch(e){showError(e)}finally{setWorking(false)} };
  const generateOpportunities = async () => { setWorking(true); try { await api(`/businesses/${businessId}/opportunities/generate`,{method:"POST"}); await loadWorkspace(); setSection("Content Studio"); }catch(e){showError(e)}finally{setWorking(false)} };
  const openOpportunityGeneration = (opportunity:Opportunity) => { setSelectedOpportunity(opportunity); setGenerateForm({content_type:opportunity.suggested_content_type,topic:opportunity.title,tone:"clear",target_keywords:opportunity.target_keywords.join(", "),audience:profileForm.target_audience,call_to_action:""}); setModal("generate"); };
  const generateContent = async (e:FormEvent) => { e.preventDefault(); setWorking(true); try { const result=await api<Content>(`/businesses/${businessId}/content/generate`,{method:"POST",body:JSON.stringify({...generateForm,title:generateForm.topic||undefined,topic:generateForm.topic||undefined,target_keywords:generateForm.target_keywords.split(",").map(v=>v.trim()).filter(Boolean),audience:generateForm.audience||undefined,call_to_action:generateForm.call_to_action||undefined,opportunity_id:selectedOpportunity?.id??undefined})}); setContent(c=>[result,...c]); setOpportunities(o=>o.map(item=>item.id===selectedOpportunity?.id?{...item,status:"accepted",content_id:result.id}:item)); setModal(null); setSelectedOpportunity(null); setGenerateForm({content_type:"blog_article",topic:"",tone:"clear",target_keywords:"",audience:"",call_to_action:""}); await loadWorkspace(); }catch(e){showError(e)}finally{setWorking(false)} };
  const saveContent = async (e:FormEvent) => { e.preventDefault(); if(!editingContent) return; setWorking(true); try { const result=await api<Content>(`/businesses/${businessId}/content/${editingContent.id}`,{method:"PATCH",body:JSON.stringify({title:editingContent.title,body:editingContent.body,meta_title:editingContent.meta_title,meta_description:editingContent.meta_description,target_keywords:editingContent.target_keywords})}); setContent(c=>c.map(i=>i.id===result.id?result:i)); setEditingContent(result); }catch(e){showError(e)}finally{setWorking(false)} };
  const optimizeContent = async (id:string) => { setWorking(true); try { const result=await api<ContentScore>(`/businesses/${businessId}/content/${id}/optimize`,{method:"POST"}); setSelectedContentScore(result); }catch(e){showError(e)}finally{setWorking(false)} };
  const connectPlatform = async (e:FormEvent) => { e.preventDefault(); setWorking(true); try { await api(`/businesses/${businessId}/publishing/connections`,{method:"POST",body:JSON.stringify({platform:newConnection.platform,account_name:newConnection.account_name||undefined,access_token:newConnection.access_token||undefined,account_url:newConnection.account_url||undefined,target_identifier:newConnection.target_identifier||undefined})}); setNewConnection({platform:"wordpress",account_name:"",access_token:"",account_url:"",target_identifier:""}); setModal(null); setConnections(await api<Connection[]>(`/businesses/${businessId}/publishing/connections`)); }catch(e){showError(e)}finally{setWorking(false)} };
  const publish = async (contentId:string, connectionId:string) => { setWorking(true); try { await api(`/businesses/${businessId}/publishing/posts/publish`,{method:"POST",body:JSON.stringify({content_id:contentId,connection_id:connectionId})}); await loadWorkspace(); }catch(e){showError(e)}finally{setWorking(false)} };
  const approveContent = async (id:string) => { setWorking(true); try { const result=await api<Content>(`/businesses/${businessId}/content/${id}`,{method:"PATCH",body:JSON.stringify({status:"ready"})}); setContent(c=>c.map(i=>i.id===result.id?result:i)); await loadWorkspace(); }catch(e){showError(e)}finally{setWorking(false)} };
  const schedule = async (contentId:string, connectionId:string, when:string) => { setWorking(true); try { await api(`/businesses/${businessId}/publishing/posts/schedule`,{method:"POST",body:JSON.stringify({content_id:contentId,connection_id:connectionId,scheduled_for:new Date(when).toISOString(),timezone_name:Intl.DateTimeFormat().resolvedOptions().timeZone})}); setModal(null); setSchedulingContent(null); await loadWorkspace(); }catch(e){showError(e)}finally{setWorking(false)} };
  const ingestDemoAnalytics = async (e:FormEvent) => { e.preventDefault(); if(!demoMetricForm.post_id) return; setWorking(true); try { const numeric=(key:string)=>Number(demoMetricForm[key as keyof typeof demoMetricForm])||0; const post=posts.find(p=>p.id===demoMetricForm.post_id); if(!post) throw new Error("Select a published post first."); const metrics:Record<string,number> = {}; for(const [key,field] of [["reach","reach"],["impressions","impressions"],["engagement","engagement"],["likes","likes"],["comments","comments"],["shares","shares"],["clicks","clicks"]] as const){ const value=numeric(field); if(value>0) metrics[key]=value; } if(!Object.keys(metrics).length) throw new Error("Enter at least one non-zero metric."); await api(`/businesses/${businessId}/analytics/metrics`,{method:"POST",body:JSON.stringify({post_id:demoMetricForm.post_id,platform:post.platform,measured_on:demoMetricForm.measured_on,source:"demo",metrics,raw_payload:{...metrics}})}); await api(`/businesses/${businessId}/analytics/snapshots/rebuild`,{method:"POST"}); setModal(null); setDemoMetricForm({post_id:"",measured_on:new Date().toISOString().slice(0,10),reach:"",impressions:"",engagement:"",likes:"",comments:"",shares:"",clicks:""}); await loadWorkspace(); }catch(e){showError(e)}finally{setWorking(false)} };
  const compareImprovement = async () => { if(!website || !improvePrev || !improveCurrent) return; setWorking(true); try { await api(`/businesses/${businessId}/websites/${website.id}/improvements/compare`,{method:"POST",body:JSON.stringify({previous_scan_id:improvePrev,current_scan_id:improveCurrent})}); setImprovements(await api<Improvement[]>(`/businesses/${businessId}/websites/${website.id}/improvements`)); }catch(e){showError(e)}finally{setWorking(false)} };
  const ask = async (e:FormEvent) => { e.preventDefault(); if(!chat.trim()) return; const q=chat.trim(); setChat(""); setMessages(m=>[...m,{role:"user",content:q}]); try { const res=await api<{role:string;content:string}>(`/businesses/${businessId}/assistant/chat`,{method:"POST",body:JSON.stringify({content:q})}); setMessages(m=>[...m,{role:"assistant",content:res.content}]); }catch(e){showError(e)} };
  const saveProfile = async (e:FormEvent) => { e.preventDefault(); setWorking(true); try { await api(`/businesses/${businessId}/profile`,{method:"PATCH",body:JSON.stringify({target_audience:profileForm.target_audience||null,brand_voice:profileForm.brand_voice||null,brand_tone:profileForm.brand_tone||null,keywords:profileForm.keywords.split(",").map(v=>v.trim()).filter(Boolean),products:profileForm.products.split(",").map(v=>v.trim()).filter(Boolean),services:profileForm.services.split(",").map(v=>v.trim()).filter(Boolean)})}); await loadWorkspace(); }catch(e){showError(e)}finally{setWorking(false)} };
  const readAll = async () => { try { await api("/notifications/read-all",{method:"POST"}); setNotifications(n=>n.map(x=>({...x,is_read:true}))); }catch(e){showError(e)} };
  const logout = () => { clearSession(); router.push("/login"); };

  const openRecs = recommendations.filter(r=>["pending","in_progress"].includes(r.status));
  const demoConnections = connections.filter(c=>c.mode==="demo").length;
  const latestSnapshot = snapshots[0];

  if (loading && !business) return <main className="loading"><div className="loader"><span></span><span></span><span></span></div><p>Loading your workspace…</p></main>;

  return <div className="app-shell">
    <aside className={`sidebar ${menuOpen ? "menu-open" : ""}`}>
      <div className="sidebar-header"><a className="brand" href="/dashboard">AURA</a><button className="menu-toggle" onClick={()=>setMenuOpen(v=>!v)} aria-label="Toggle navigation">{menuOpen?"×":"☰"}</button></div>
      <p className="sidebar-tag">Analyze. Optimize.<br/>Publish. Grow.</p>
      {businesses.length>0 && <label className="workspace-picker"><span>WORKSPACE</span><select value={businessId} onChange={e=>setBusinessId(e.target.value)}>{businesses.map(b=><option value={b.id} key={b.id}>{b.name}</option>)}</select></label>}
      <nav>{sections.map(item=><button key={item} className={`nav-item ${section===item?"active":""}`} onClick={()=>{setSection(item);setMenuOpen(false)}}><span className="nav-dot"></span>{item}</button>)}</nav>
      <div className="sidebar-bottom"><div className="cap-mini"><span className="live-dot"></span><div><strong>{capabilities?.ai.enabled?"Gemini connected":"Local demo mode"}</strong><small>{demoConnections} demo connector{demoConnections===1?"":"s"}</small></div></div><button className="nav-item signout" onClick={logout}>Sign out</button></div>
    </aside>

    <main className="main">
      <header className="topbar"><div><p className="eyebrow">DIGITAL VISIBILITY WORKSPACE</p><h1>{section}</h1><p className="top-sub">{business?.name ?? "Set up your business to begin"}</p></div><div className="header-actions"><button className="button secondary" onClick={()=>setModal("business")}>+ Business</button><button className="button" onClick={startScan} disabled={working || !website}>{working?"Working…":"Scan website"}</button></div></header>
      {error && <div className="alert"><strong>Action needs attention</strong><span>{error}</span><button onClick={()=>setError("")}>×</button></div>}
      {!business ? <Empty title="Create your first business" text="AURA needs a business profile before it can analyze a website or generate grounded content." action="+ Add business" onClick={()=>setModal("business")}/> : <>
        {section==="Overview" && <Overview business={business} website={website} scan={scan} seo={seo} ai={ai} historySeo={historySeo} historyAi={historyAi} recs={openRecs} recSummary={recSummary} latestSnapshot={latestSnapshot} activity={activities.slice(0,5)} onScan={startScan} onSection={setSection} onSite={()=>setModal("site")} />}
        {section==="Websites & scans" && <WebsitesPanel business={business} website={website} scans={scans} scan={scan} seo={seo} ai={ai} monitorForm={monitorForm} setMonitorForm={setMonitorForm} onMonitoringSave={updateMonitoring} onScan={startScan} onSite={()=>setModal("site")} working={working} />}
        {section==="Recommendations" && <RecommendationsPanel items={recommendations} summary={recSummary} onUpdate={updateRec} onRegenerate={regenerateRecs} working={working} />}
        {section==="Content Studio" && <ContentPanel items={content} opportunities={opportunities} onGenerate={()=>{setSelectedOpportunity(null);setModal("generate")}} onGenerateOpp={generateOpportunities} onGenerateOpportunity={openOpportunityGeneration} onEdit={setEditingContent} onOptimize={optimizeContent} onApprove={approveContent} selectedScore={selectedContentScore} onCloseScore={()=>setSelectedContentScore(null)} onOpportunityStatus={async(id,status)=>{await api(`/businesses/${businessId}/opportunities/${id}`,{method:"PATCH",body:JSON.stringify({status})});await loadWorkspace();}} />}
        {section==="Publishing" && <PublishingPanel connections={connections} posts={posts} scheduled={scheduled} content={content} onConnect={()=>setModal("connect")} onPublish={publish} onSchedule={(id,conn)=>{setSchedulingContent(content.find(c=>c.id===id)||null);setModal(`schedule:${conn}`)}} />}
        {section==="Analytics" && <AnalyticsPanel snapshots={snapshots} posts={posts.filter(p=>p.status==="published")} onAddDemo={()=>setModal("analytics-demo")} onRebuild={async()=>{setWorking(true);try{await api(`/businesses/${businessId}/analytics/snapshots/rebuild`,{method:"POST"});await loadWorkspace()}catch(e){showError(e)}finally{setWorking(false)}}} latestSnapshot={latestSnapshot} />}
        {section==="Assistant" && <AssistantPanel messages={messages} value={chat} onChange={setChat} onAsk={ask} />}
        {section==="Improvements" && <ImprovementsPanel improvements={improvements} scans={scans} previous={improvePrev} current={improveCurrent} setPrevious={setImprovePrev} setCurrent={setImproveCurrent} onCompare={compareImprovement} />}
        {section==="Notifications" && <NotificationsPanel notifications={notifications} activities={activities} onReadAll={readAll} />}
        {section==="Settings" && <SettingsPanel business={business} profileForm={profileForm} setProfileForm={setProfileForm} onSave={saveProfile} capabilities={capabilities} working={working} />}
      </>}
    </main>

    {modal==="business" && <Modal title="Create business" onClose={()=>setModal(null)}><form className="form-grid" onSubmit={createBusiness}><label>Business name<input value={name} onChange={e=>setName(e.target.value)} required /></label><label>Industry<input value={industry} onChange={e=>setIndustry(e.target.value)} placeholder="Bakery, consulting, retail…" /></label><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button" disabled={working}>{working?"Creating…":"Create business"}</button></div></form></Modal>}
    {modal==="site" && <Modal title="Add website" onClose={()=>setModal(null)}><form className="form-grid" onSubmit={addWebsite}><label>Website URL<input type="url" value={siteUrl} onChange={e=>setSiteUrl(e.target.value)} placeholder="https://example.com" required /></label><p className="helper">AURA will crawl publicly accessible HTML pages, respect robots.txt, and use a 20-page scan cap.</p><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button" disabled={working}>{working?"Saving…":"Add website"}</button></div></form></Modal>}
    {modal==="generate" && <Modal title="Create content with business context" onClose={()=>setModal(null)}><form className="form-grid" onSubmit={generateContent}><label>Content type<select value={generateForm.content_type} onChange={e=>setGenerateForm({...generateForm,content_type:e.target.value})}><option value="blog_article">Blog article</option><option value="faq">FAQ</option><option value="meta_title">Meta title</option><option value="meta_description">Meta description</option><option value="product_description">Product description</option><option value="linkedin_post">LinkedIn post</option><option value="instagram_caption">Instagram caption</option><option value="reddit_post">Reddit post</option><option value="facebook_post">Facebook post</option><option value="marketing_email">Marketing email</option><option value="cta">Call to action</option><option value="landing_copy">Landing page copy</option></select></label><label>Topic<input value={generateForm.topic} onChange={e=>setGenerateForm({...generateForm,topic:e.target.value})} placeholder="e.g. How to choose a birthday cake" required /></label><label>Target keywords<input value={generateForm.target_keywords} onChange={e=>setGenerateForm({...generateForm,target_keywords:e.target.value})} placeholder="cake, birthday cake, Mumbai" /></label><label>Audience<input value={generateForm.audience} onChange={e=>setGenerateForm({...generateForm,audience:e.target.value})} placeholder="Busy parents in Mumbai" /></label><label>Tone<select value={generateForm.tone} onChange={e=>setGenerateForm({...generateForm,tone:e.target.value})}><option>clear</option><option>friendly</option><option>professional</option><option>persuasive</option><option>educational</option></select></label><label>Call to action<input value={generateForm.call_to_action} onChange={e=>setGenerateForm({...generateForm,call_to_action:e.target.value})} placeholder="Book a consultation" /></label><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button" disabled={working}>{working?"Generating…":"Generate content"}</button></div><p className="helper">Live content uses Gemini 2.5 Flash when configured. Otherwise AURA clearly labels demo output.</p></form></Modal>}
    {modal==="connect" && <Modal title="Connect publishing destination" onClose={()=>setModal(null)}><form className="form-grid" onSubmit={connectPlatform}><label>Platform<select value={newConnection.platform} onChange={e=>setNewConnection({...newConnection,platform:e.target.value})}><option value="wordpress">WordPress</option><option value="linkedin">LinkedIn</option><option value="reddit">Reddit</option><option value="instagram">Instagram (demo)</option><option value="facebook">Facebook (demo)</option><option value="x">X (demo)</option></select></label><label>Account label<input value={newConnection.account_name} onChange={e=>setNewConnection({...newConnection,account_name:e.target.value})} placeholder="My business account" /></label>{(newConnection.platform==="wordpress"||newConnection.platform==="linkedin"||newConnection.platform==="reddit")&&<><label>Access token<input type="password" autoComplete="off" value={newConnection.access_token} onChange={e=>setNewConnection({...newConnection,access_token:e.target.value})} placeholder="Paste the platform access token" /></label>{newConnection.platform==="wordpress"&&<label>WordPress site URL<input value={newConnection.account_url} onChange={e=>setNewConnection({...newConnection,account_url:e.target.value})} placeholder="https://your-site.com" /></label>}{newConnection.platform==="linkedin"&&<label>Author URN<input value={newConnection.target_identifier} onChange={e=>setNewConnection({...newConnection,target_identifier:e.target.value})} placeholder="urn:li:person:xxxxxxxx" /></label>}{newConnection.platform==="reddit"&&<label>Subreddit<input value={newConnection.target_identifier} onChange={e=>setNewConnection({...newConnection,target_identifier:e.target.value})} placeholder="Subreddit name, without r/" /></label>}</>}<p className="helper">With an access token the connection is live and posts really go out; the token is stored encrypted and never shown again. Leave the token empty to create a clearly labelled demo connection with the same workflow. LinkedIn tokens expire after about 60 days and just need a fresh paste here.</p><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button" disabled={working}>{working?"Connecting…":"Connect"}</button></div></form></Modal>}
    {modal==="analytics-demo" && <Modal title="Add demo analytics" onClose={()=>setModal(null)}><form className="form-grid" onSubmit={ingestDemoAnalytics}><p className="helper">This uses explicitly labelled demo data so the full analytics dashboard can be demonstrated without paid platform APIs.</p><label>Published post<select value={demoMetricForm.post_id} onChange={e=>setDemoMetricForm({...demoMetricForm,post_id:e.target.value})} required><option value="">Choose…</option>{posts.filter(p=>p.status==="published").map(p=><option key={p.id} value={p.id}>{pretty(p.platform)} · {p.id.slice(0,8)}</option>)}</select></label><label>Date<input type="date" value={demoMetricForm.measured_on} onChange={e=>setDemoMetricForm({...demoMetricForm,measured_on:e.target.value})} required /></label><div className="metric-input-grid">{([['reach','Reach'],['impressions','Impressions'],['engagement','Engagement'],['likes','Likes'],['comments','Comments'],['shares','Shares'],['clicks','Clicks']] as const).map(([key,label])=><label key={key}>{label}<input type="number" min="0" value={demoMetricForm[key]} onChange={e=>setDemoMetricForm({...demoMetricForm,[key]:e.target.value})} /></label>)}</div><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setModal(null)}>Cancel</button><button className="button" disabled={working||!demoMetricForm.post_id}>{working?"Saving…":"Add demo metrics"}</button></div></form></Modal>}
    {modal?.startsWith("schedule:") && <ScheduleModal content={schedulingContent} connectionId={modal.split(":")[1]} onClose={()=>{setModal(null);setSchedulingContent(null)}} onSchedule={schedule} />}
    {editingContent && !modal && <Modal title="Edit content" onClose={()=>setEditingContent(null)}><form className="form-grid" onSubmit={saveContent}><label>Title<input value={editingContent.title} onChange={e=>setEditingContent({...editingContent,title:e.target.value})}/></label><label>Body<textarea className="editor" value={editingContent.body} onChange={e=>setEditingContent({...editingContent,body:e.target.value})}/></label><label>Meta description<input value={editingContent.meta_description??""} onChange={e=>setEditingContent({...editingContent,meta_description:e.target.value})}/></label><div className="modal-actions"><button type="button" className="button secondary" onClick={()=>setEditingContent(null)}>Close</button><button className="button" disabled={working}>{working?"Saving…":"Save changes"}</button></div></form></Modal>}
  </div>;
}

function Overview({ business, website, scan, seo, ai, historySeo, historyAi, recs, recSummary, latestSnapshot, activity, onScan, onSection, onSite }: {business:Business;website:Website|null;scan:Scan|null;seo:SeoReport|null;ai:AiReport|null;historySeo:number[];historyAi:number[];recs:Recommendation[];recSummary:RecommendationList["summary"]|null;latestSnapshot?:Snapshot;activity:Activity[];onScan:()=>void;onSection:(s:Section)=>void;onSite:()=>void}) {
  return <div className="workspace-grid">
    <section className="hero-card"><div><p className="eyebrow">{website?"PRIMARY WEBSITE":"GET STARTED"}</p><h2>{website ? "Your visibility snapshot" : "Connect a website to begin"}</h2><p>{website ? `AURA is tracking ${website.normalized_url ?? website.url}.` : "Start with one public website; the scanner and recommendation engine will build the evidence base."}</p><div className="hero-actions">{website?<button className="button" onClick={onScan}>Run a fresh scan</button>:<button className="button" onClick={onSite}>Add website</button>}<button className="button secondary" onClick={()=>onSection("Recommendations")}>View action plan</button></div></div><div className="hero-signal"><SignalRing value={seo?.overall_score} label="SEO" /><SignalRing value={ai?.overall_score} label="AI SEARCH" small /></div></section>
    <div className="score-grid"><ScoreCard label="SEO health" value={seo?.overall_score} grade={seo?.grade} trend={historySeo} /><ScoreCard label="AI-search readiness" value={ai?.overall_score} grade={ai?.grade} trend={historyAi} /><ScoreCard label="Open recommendations" value={recSummary?.open ?? 0} suffix="actions" /></div>
    <section className="panel-grid two"><div className="panel"><div className="panel-head"><div><p className="eyebrow">SCAN STATUS</p><h3>{scan?`Scan #${scan.sequence??"-"}`:"No scan yet"}</h3></div>{scan && <Badge tone={scan.status}>{pretty(scan.status)}</Badge>}</div>{scan?<><div className="progress"><span style={{width:`${scan.progress_percent}%`}}></span></div><div className="progress-label"><span>{scan.progress_message ?? pretty(scan.status)}</span><span>{scan.progress_percent}%</span></div><div className="mini-stats"><span><strong>{scan.pages_crawled}</strong> pages analyzed</span><span><strong>{scan.pages_failed}</strong> failed</span><span><strong>{scan.pages_discovered}</strong> discovered</span></div></>:<Empty title="Run your first scan" text="The scan creates the evidence used by your scores, recommendations and improvement history." action="Scan website" onClick={onScan}/>}</div><div className="panel"><div className="panel-head"><div><p className="eyebrow">SCORE TRENDS</p><h3>Visibility over time</h3></div></div><div className="trend-grid"><div><span>SEO</span><Sparkline values={historySeo} label="SEO trend"/></div><div><span>AI-search</span><Sparkline values={historyAi} label="AI-search trend"/></div></div></div></section>
    <section className="panel-grid two"><div className="panel"><div className="panel-head"><div><p className="eyebrow">PRIORITY ACTIONS</p><h3>{recs.length?"What to fix next":"No open recommendations"}</h3></div><button className="text-link" onClick={()=>onSection("Recommendations")}>View all</button></div>{recs.length?<div className="stack-list">{recs.slice(0,5).map(r=><div className="list-row" key={r.id}><div><strong>{r.title}</strong><p>{r.suggested_action}</p></div><div className="row-meta"><Badge tone={r.priority_bucket}>{pretty(r.priority_bucket)}</Badge><span>+{r.estimated_score_gain?.toFixed(1)??"0"}</span></div></div>)}</div>:<div className="success-box">✓ Your current scan has no open actions in the recommendation queue.</div>}</div><div className="panel"><div className="panel-head"><div><p className="eyebrow">PERFORMANCE</p><h3>{latestSnapshot?dateText(latestSnapshot.snapshot_date):"Waiting for analytics"}</h3></div><button className="text-link" onClick={()=>onSection("Analytics")}>Analytics</button></div>{latestSnapshot?<div className="metric-grid"><Metric label="Reach" value={compact(latestSnapshot.total_reach)} provenance={provenanceText(latestSnapshot)}/><Metric label="Engagement" value={compact(latestSnapshot.total_engagement)} provenance={provenanceText(latestSnapshot)}/><Metric label="Clicks" value={compact(latestSnapshot.total_clicks)} provenance={provenanceText(latestSnapshot)}/><Metric label="Posts" value={String(latestSnapshot.posts_published)} provenance="Derived"/></div>:<div className="empty-inline">Analytics remain blank until real or explicitly entered/demo metrics exist.</div>}</div></section>
    <section className="panel"><div className="panel-head"><div><p className="eyebrow">ACTIVITY</p><h3>Recent workspace events</h3></div></div>{activity.length?<div className="activity-list">{activity.map(a=><div key={a.id}><span className="activity-dot"></span><div><strong>{pretty(a.action)}</strong><p>{a.description}</p></div><time>{dateText(a.created_at)}</time></div>)}</div>:<div className="empty-inline">Activity will appear as you scan, generate, publish and improve.</div>}</section>
  </div>;
}

function SignalRing({ value, label, small }: { value?: number | null; label: string; small?: boolean }) {
  const radius = 48.5;
  const circumference = 2 * Math.PI * radius;
  const clamped = value == null ? 0 : Math.min(100, Math.max(0, value));
  return <div className={`signal-ring${small ? " small" : ""}`}>
    <svg className="ring-svg" viewBox="0 0 100 100" aria-hidden="true">
      <circle className="ring-track" cx="50" cy="50" r={radius} />
      {value != null && <circle className={`ring-arc ${scoreClass(value)}`} cx="50" cy="50" r={radius} strokeDasharray={`${(clamped / 100) * circumference} ${circumference}`} transform="rotate(-90 50 50)" />}
    </svg>
    <span>{value == null ? "-" : Math.round(value)}</span>
    <small>{label}</small>
  </div>;
}
function ScoreCard({label,value,grade,trend,suffix}:{label:string;value?:number;grade?:string;trend?:number[]; suffix?:string}) { return <div className={`score-card ${value!=null?scoreClass(value):""}`}><div className="score-top"><span>{label}</span>{grade&&<Badge tone={grade}>{pretty(grade)}</Badge>}</div><strong>{value==null?"-":Math.round(value)}</strong>{suffix&&<small>{suffix}</small>}{trend&&trend.length>1&&<Sparkline values={trend} label={`${label} trend`}/>}</div>; }
function Metric({label,value,provenance}:{label:string;value:string;provenance:string}) { return <div className="metric"><span>{label}</span><strong>{value}</strong><small>{provenance}</small></div>; }

function WebsitesPanel({business,website,scans,scan,seo,ai,monitorForm,setMonitorForm,onMonitoringSave,onScan,onSite,working}:{business:Business;website:Website|null;scans:Scan[];scan:Scan|null;seo:SeoReport|null;ai:AiReport|null;monitorForm:{enabled:boolean;frequency:string;hour:number;minute:number;day_of_week:number;timezone:string};setMonitorForm:(v:{enabled:boolean;frequency:string;hour:number;minute:number;day_of_week:number;timezone:string})=>void;onMonitoringSave:(nextForm?:{enabled:boolean;frequency:string;hour:number;minute:number;day_of_week:number;timezone:string})=>void;onScan:()=>void;onSite:()=>void;working:boolean}) { return <div className="workspace-grid"><section className="panel"><div className="panel-head"><div><p className="eyebrow">WEBSITES</p><h3>{website?.normalized_url ?? website?.url ?? "No websites"}</h3></div><div className="panel-actions"><button className="button secondary" onClick={onSite}>+ Website</button><button className="button" onClick={onScan} disabled={!website}>Scan</button></div></div>{website?<><div className="detail-grid"><div><span>Robots</span><strong>{website.robots_txt_found==null?"Not checked":website.robots_txt_found?"Found":"Missing"}</strong></div><div><span>Sitemap</span><strong>{website.sitemap_found==null?"Not checked":website.sitemap_found?"Found":"Missing"}</strong></div><div><span>CMS</span><strong>{website.detected_cms??"Not detected"}</strong></div><div><span>Last scan</span><strong>{dateText(website.last_scan_at)}</strong></div></div><div className="monitor-card"><div><p className="eyebrow">CONTINUOUS MONITORING</p><h4>{monitorForm.enabled?"Scheduled analysis is on":"Scheduled analysis is off"}</h4><p>Let AURA periodically re-scan the site and feed new findings into the same scoring and improvement pipeline.</p></div><div className="monitor-controls"><label><span>Schedule</span><select value={monitorForm.frequency} onChange={e=>setMonitorForm({...monitorForm,frequency:e.target.value})}><option value="daily">Daily</option><option value="weekly">Weekly</option></select></label><label><span>Time</span><input type="time" value={`${String(monitorForm.hour).padStart(2,"0")}:${String(monitorForm.minute).padStart(2,"0")}`} onChange={e=>{const [h,m]=e.target.value.split(":").map(Number);setMonitorForm({...monitorForm,hour:h,minute:m})}} /></label>{monitorForm.frequency==="weekly"&&<label><span>Day</span><select value={monitorForm.day_of_week} onChange={e=>setMonitorForm({...monitorForm,day_of_week:Number(e.target.value)})}>{["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"].map((d,i)=><option key={d} value={i}>{d}</option>)}</select></label>}<label><span>Timezone</span><input value={monitorForm.timezone} onChange={e=>setMonitorForm({...monitorForm,timezone:e.target.value})} placeholder="Asia/Kolkata" /></label><button className="button" onClick={()=>onMonitoringSave({...monitorForm,enabled:!monitorForm.enabled})} disabled={working}>{monitorForm.enabled?"Turn off & save":"Enable & save"}</button></div><div className="monitor-save"><span>{website.last_monitor_run_at?`Last scheduled run ${dateText(website.last_monitor_run_at)}`:"No scheduled run yet"}</span><button className="text-button" onClick={() => onMonitoringSave()} disabled={working}>Save schedule</button></div></div></>:<Empty title="No website registered" text="Add a primary website so AURA can create a measurable baseline." action="Add website" onClick={onSite}/>}</section>{scan&&<section className="panel"><div className="panel-head"><div><p className="eyebrow">LATEST RESULTS</p><h3>Scan #{scan.sequence}</h3></div><div className="score-pills"><Badge tone={scan.status}>{pretty(scan.status)}</Badge>{seo&&<Badge tone={seo.grade}>{Math.round(seo.overall_score)} SEO</Badge>}{ai&&<Badge tone={ai.grade}>{Math.round(ai.overall_score)} AI-search</Badge>}</div></div><div className="result-grid"><div className="result-block"><span>Progress</span><strong>{scan.progress_percent}%</strong><p>{scan.progress_message}</p></div><div className="result-block"><span>Pages</span><strong>{scan.pages_crawled}</strong><p>{scan.pages_failed} fetch failures</p></div><div className="result-block"><span>Coverage</span><strong>{scan.pages_discovered}</strong><p>{scan.hit_page_limit?"20-page cap reached":"Discovery complete"}</p></div></div></section>}<section className="panel"><div className="panel-head"><div><p className="eyebrow">SCAN HISTORY</p><h3>Immutable scan runs</h3></div></div><div className="table-wrap"><table><thead><tr><th>Run</th><th>Trigger</th><th>Status</th><th>Pages</th><th>Completed</th></tr></thead><tbody>{scans.map(s=><tr key={s.id}><td>#{s.sequence}</td><td>{pretty((s as Scan & {trigger?:string}).trigger??"manual")}</td><td><Badge tone={s.status}>{pretty(s.status)}</Badge></td><td>{s.pages_crawled}</td><td>{dateText(s.completed_at)}</td></tr>)}</tbody></table></div></section></div> }

function RecommendationsPanel({items,summary,onUpdate,onRegenerate,working}:{items:Recommendation[];summary:RecommendationList["summary"]|null;onUpdate:(id:string,status:string)=>void;onRegenerate:()=>void;working:boolean}) { return <div className="workspace-grid"><section className="summary-strip"><div><span>Open</span><strong>{summary?.open??0}</strong></div><div><span>Total</span><strong>{summary?.total??0}</strong></div><div><span>Estimated recoverable</span><strong>+{summary?.estimated_total_gain?.toFixed(1)??"0.0"}</strong></div></section><section className="panel"><div className="panel-head"><div><p className="eyebrow">ACTION ENGINE</p><h3>Prioritized recommendations</h3></div><button className="button secondary" onClick={onRegenerate} disabled={working}>{working?"Refreshing…":"Regenerate from latest scan"}</button></div>{items.length?<div className="recommendation-grid">{items.map(r=><article className="recommendation-card" key={r.id}><div className="card-kicker"><Badge tone={r.severity}>{pretty(r.severity)}</Badge><Badge tone={r.priority_bucket}>{pretty(r.priority_bucket)}</Badge><span>+{r.estimated_score_gain?.toFixed(1)??"0.0"} pts est.</span></div><h4>{r.title}</h4><p>{r.description}</p><div className="rec-action"><strong>Next step</strong><p>{r.suggested_action}</p></div><div className="card-foot"><span>{r.affected_page_count} affected page{r.affected_page_count===1?"":"s"}</span><span>{pretty(r.status)}</span><div>{r.status==="pending"&&<button className="text-button" onClick={()=>onUpdate(r.id,"in_progress")}>Start</button>}{r.status==="in_progress"&&<button className="text-button" onClick={()=>onUpdate(r.id,"completed")}>Mark done</button>}{["pending","in_progress"].includes(r.status)&&<button className="text-button muted" onClick={()=>onUpdate(r.id,"dismissed")}>Dismiss</button>}</div></div></article>)}</div>:<Empty title="No open recommendations" text="AURA will create new recommendations when a scan finds measurable gaps."/>}</section></div>}

function ContentPanel({items,opportunities,onGenerate,onGenerateOpp,onGenerateOpportunity,onEdit,onOptimize,onApprove,selectedScore,onCloseScore,onOpportunityStatus}:{items:Content[];opportunities:Opportunity[];onGenerate:()=>void;onGenerateOpp:()=>void;onGenerateOpportunity:(opportunity:Opportunity)=>void;onEdit:(item:Content)=>void;onOptimize:(id:string)=>void;onApprove:(id:string)=>void;selectedScore:ContentScore|null;onCloseScore:()=>void;onOpportunityStatus:(id:string,status:string)=>void}) { return <div className="workspace-grid"><section className="panel"><div className="panel-head"><div><p className="eyebrow">CONTENT INTELLIGENCE</p><h3>Opportunities from real findings</h3></div><div className="panel-actions"><button className="button secondary" onClick={onGenerateOpp}>Refresh opportunities</button><button className="button" onClick={onGenerate}>Generate content</button></div></div>{opportunities.length?<div className="opportunity-grid">{opportunities.slice(0,6).map(o=><article className="opportunity-card" key={o.id}><div className="card-kicker"><Badge tone={o.impact}>{pretty(o.impact)} impact</Badge><span>{pretty(o.suggested_content_type)}</span></div><h4>{o.title}</h4><p>{o.rationale}</p><div className="outline">{o.suggested_outline.slice(0,4).map(line=><span key={line}>• {line}</span>)}</div><div className="card-foot"><span>{pretty(o.status)}</span><div>{o.status==="suggested"&&<><button className="text-button" onClick={()=>onGenerateOpportunity(o)}>Generate draft</button><button className="text-button muted" onClick={()=>onOpportunityStatus(o.id,"dismissed")}>Dismiss</button></>}{o.status==="accepted"&&!o.content_id&&<button className="text-button" onClick={()=>onGenerateOpportunity(o)}>Generate draft</button>}</div></div></article>)}</div>:<div className="empty-inline">No opportunities yet. Run a scan and refresh this section to turn content-shaped findings into ideas.</div>}</section><section className="panel"><div className="panel-head"><div><p className="eyebrow">CONTENT LIBRARY</p><h3>Drafts, versions and scores</h3></div></div>{items.length?<div className="content-list">{items.map(item=><article className="content-row" key={item.id}><div className="content-main"><div className="content-title"><h4>{item.title}</h4><Badge tone={item.generation_mode}>{item.generation_mode==="live"?"Gemini":"Demo/Manual"}</Badge><Badge tone={item.status}>{pretty(item.status)}</Badge></div><p>{pretty(item.content_type)} · {item.word_count} words · v{item.current_version}</p><p className="truncate">{item.body}</p></div><div className="content-actions"><div className={`content-score ${scoreClass(item.latest_score??0)}`}>{item.latest_score==null?"-":Math.round(item.latest_score)}</div><button className="text-button" onClick={()=>onEdit(item)}>Edit</button><button className="text-button" onClick={()=>onOptimize(item.id)}>Optimize</button>{["draft","generating"].includes(item.status)&&<button className="text-button" onClick={()=>onApprove(item.id)}>Mark ready</button>}</div></article>)}</div>:<Empty title="No content yet" text="Generate a business-grounded article, FAQ or social post. Each draft is versioned and can be optimized before publishing." action="Generate content" onClick={onGenerate}/>}</section>{selectedScore&&<Modal title="Content optimization" onClose={onCloseScore}><div className="score-hero"><div className={`big-score ${scoreClass(selectedScore.overall_score)}`}>{Math.round(selectedScore.overall_score)}</div><div><p className="eyebrow">CONTENT SCORE</p><h3>{pretty(selectedScore.grade)}</h3><p>{selectedScore.readability_score?`Readability ${selectedScore.readability_score}`:"Readability not available yet"}</p></div></div><div className="detail-grid">{Object.entries(selectedScore.category_scores).map(([key,val])=><div key={key}><span>{pretty(key)}</span><strong>{val.earned}/{val.available}</strong></div>)}</div>{selectedScore.issues.length>0&&<div className="issue-list">{selectedScore.issues.map(i=><div key={i.rule_id}><Badge tone={i.severity}>{pretty(i.severity)}</Badge><div><strong>{i.title}</strong><p>{i.description}</p></div></div>)}</div>}{selectedScore.suggestions.length>0&&<div className="success-box">{selectedScore.suggestions.map(s=><div key={s.rule_id}>{s.title}: {s.description}</div>)}</div>}</Modal>}</div>}

function PublishingPanel({connections,posts,scheduled,content,onConnect,onPublish,onSchedule}:{connections:Connection[];posts:Post[];scheduled:ScheduledPost[];content:Content[];onConnect:()=>void;onPublish:(contentId:string,connectionId:string)=>void;onSchedule:(contentId:string,connectionId:string)=>void}) { const [selectedContent,setSelectedContent]=useState(content[0]?.id??""); const [selectedConn,setSelectedConn]=useState(connections[0]?.id??""); useEffect(()=>{if(!selectedContent&&content[0])setSelectedContent(content[0].id)},[content,selectedContent]);useEffect(()=>{if(!selectedConn&&connections[0])setSelectedConn(connections[0].id)},[connections,selectedConn]); const postById=new Map(posts.map(p=>[p.id,p])); const contentById=new Map(content.map(c=>[c.id,c])); return <div className="workspace-grid"><section className="panel"><div className="panel-head"><div><p className="eyebrow">PUBLISHING CENTER</p><h3>Approved content to platforms</h3></div><button className="button" onClick={onConnect}>+ Connect platform</button></div><div className="connector-grid">{connections.map(c=><article className="connector" key={c.id}><div className="connector-icon">{c.platform.slice(0,2).toUpperCase()}</div><div><strong>{c.account_name??pretty(c.platform)}</strong><p>{pretty(c.platform)} · {c.mode === "live" ? "Live" : "Demo"}</p></div><Badge tone={c.mode}>{c.mode}</Badge></article>)}</div>{!connections.length&&<div className="empty-inline">No platforms connected. Demo mode is available immediately; real publishing requires the platform's official credentials.</div>}</section><section className="panel"><div className="panel-head"><div><p className="eyebrow">PUBLISH</p><h3>Send or schedule a draft</h3></div></div><div className="publish-form"><label>Content<select value={selectedContent} onChange={e=>setSelectedContent(e.target.value)}>{content.map(c=><option value={c.id} key={c.id}>{c.title}</option>)}</select></label><label>Destination<select value={selectedConn} onChange={e=>setSelectedConn(e.target.value)}>{connections.map(c=><option value={c.id} key={c.id}>{c.account_name ?? c.platform}</option>)}</select></label><div className="hero-actions"><button className="button" disabled={!selectedContent||!selectedConn} onClick={()=>onPublish(selectedContent,selectedConn)}>Publish now</button><button className="button secondary" disabled={!selectedContent||!selectedConn} onClick={()=>onSchedule(selectedContent,selectedConn)}>Schedule</button></div></div></section><section className="panel"><div className="panel-head"><div><p className="eyebrow">RECENT POSTS</p><h3>Publishing history</h3></div></div><div className="table-wrap"><table><thead><tr><th>Platform</th><th>Mode</th><th>Status</th><th>Published</th><th>Error</th></tr></thead><tbody>{posts.map(p=><tr key={p.id}><td>{pretty(p.platform)}</td><td><Badge tone={p.mode}>{p.mode}</Badge></td><td><Badge tone={p.status}>{pretty(p.status)}</Badge></td><td>{dateText(p.published_at)}</td><td>{p.error_message ?? "-"}</td></tr>)}</tbody></table></div></section><section className="panel"><div className="panel-head"><div><p className="eyebrow">SCHEDULER</p><h3>Queued publishing jobs</h3></div></div>{scheduled.length?<div className="stack-list">{scheduled.map(s=>{const post=postById.get(s.post_id);const item=post?contentById.get(post.content_id):undefined;return <div className="list-row" key={s.id}><div><strong>{item?.title ?? "Scheduled post"}</strong><p>{post?`${pretty(post.platform)} · `:""}{dateText(s.scheduled_for)} · {s.timezone_name} · retries {s.retry_count}/{s.max_retries}{s.error_message?` · ${s.error_message}`:""}</p></div><Badge tone={s.status}>{pretty(s.status)}</Badge></div>})}</div>:<div className="empty-inline">No scheduled posts yet. Schedule a draft from the panel above and it will appear here with its retry state.</div>}</section></div>}

function AnalyticsPanel({snapshots,posts,onAddDemo,onRebuild,latestSnapshot}:{snapshots:Snapshot[];posts:Post[];onAddDemo:()=>void;onRebuild:()=>void;latestSnapshot?:Snapshot}) { const reach=snapshots.map(s=>s.total_reach).slice().reverse();const eng=snapshots.map(s=>s.total_engagement).slice().reverse();return <div className="workspace-grid"><section className="summary-strip"><div><span>Latest reach</span><strong>{latestSnapshot?compact(latestSnapshot.total_reach):"-"}</strong></div><div><span>Latest engagement</span><strong>{latestSnapshot?compact(latestSnapshot.total_engagement):"-"}</strong></div><div><span>Latest clicks</span><strong>{latestSnapshot?compact(latestSnapshot.total_clicks):"-"}</strong></div><div><span>Data origin</span><strong>{latestSnapshot?provenanceText(latestSnapshot):"-"}</strong></div></section><section className="panel"><div className="panel-head"><div><p className="eyebrow">ANALYTICS</p><h3>Performance snapshots</h3></div><div className="panel-actions"><button className="button secondary" onClick={onAddDemo} disabled={!posts.length}>Add demo metrics</button><button className="button secondary" onClick={onRebuild}>Rebuild snapshots</button></div></div><div className="analytics-charts"><div><div className="chart-head"><strong>Reach</strong><span>daily rollup</span></div><Sparkline values={reach} label="Reach trend"/></div><div><div className="chart-head"><strong>Engagement</strong><span>daily rollup</span></div><Sparkline values={eng} label="Engagement trend"/></div></div><p className="helper">AURA never invents platform metrics. Each snapshot carries real/demo provenance from its underlying data.</p></section><section className="panel"><div className="table-wrap"><table><thead><tr><th>Date</th><th>Platform</th><th>Reach</th><th>Impressions</th><th>Engagement</th><th>Clicks</th><th>Origin</th></tr></thead><tbody>{snapshots.map(s=><tr key={s.id}><td>{s.snapshot_date}</td><td>{s.platform??"All"}</td><td>{compact(s.total_reach)}</td><td>{compact(s.total_impressions)}</td><td>{compact(s.total_engagement)}</td><td>{compact(s.total_clicks)}</td><td>{Object.keys(s.source_breakdown ?? {}).length?Object.keys(s.source_breakdown).map(k=><Badge key={k} tone={k}>{pretty(k)}</Badge>):(s.has_demo_data?<Badge tone="demo">Demo</Badge>:s.has_real_data?<Badge tone="live">Platform API</Badge>:<Badge tone="neutral">Derived</Badge>)}</td></tr>)}</tbody></table></div></section></div>}

function AssistantPanel({messages,value,onChange,onAsk}:{messages:{role:string;content:string}[];value:string;onChange:(v:string)=>void;onAsk:(e:FormEvent)=>void}) { return <div className="assistant-shell panel"><div className="assistant-head"><div><p className="eyebrow">MARKETING ASSISTANT</p><h3>Ask about your evidence</h3><p>Answers are grounded in the business context already available to AURA.</p></div></div><div className="messages">{messages.length?messages.map((m,i)=><div key={i} className={`bubble ${m.role}`}>{m.content}</div>):<div className="empty-inline">Try “What should I fix first?”, “Explain my SEO score”, or “Give me three content ideas for this business.”</div>}</div><form className="chat-form" onSubmit={onAsk}><textarea value={value} onChange={e=>onChange(e.target.value)} placeholder="Ask AURA about your current visibility…"/><button className="button">Send</button></form></div>}

function ImprovementsPanel({improvements,scans,previous,current,setPrevious,setCurrent,onCompare}:{improvements:Improvement[];scans:Scan[];previous:string;current:string;setPrevious:(v:string)=>void;setCurrent:(v:string)=>void;onCompare:()=>void}) { return <div className="workspace-grid"><section className="panel"><div className="panel-head"><div><p className="eyebrow">CONTINUOUS IMPROVEMENT</p><h3>Compare two immutable scans</h3></div></div><div className="compare-form"><label>Previous scan<select value={previous} onChange={e=>setPrevious(e.target.value)}><option value="">Choose…</option>{scans.map(s=><option value={s.id} key={s.id}>#{s.sequence} · {pretty(s.status)}</option>)}</select></label><label>Current scan<select value={current} onChange={e=>setCurrent(e.target.value)}><option value="">Choose…</option>{scans.map(s=><option value={s.id} key={s.id}>#{s.sequence} · {pretty(s.status)}</option>)}</select></label><button className="button" disabled={!previous||!current||previous===current} onClick={onCompare}>Compare</button></div></section><section className="panel"><div className="panel-head"><div><p className="eyebrow">IMPROVEMENT HISTORY</p><h3>Observed change, not promises</h3></div></div>{improvements.length?<div className="improvement-grid">{improvements.map(i=><article className="improvement-card" key={i.id}><div className="comparison-values"><div><span>SEO</span><strong>{i.previous_seo_score.toFixed(1)} to {i.current_seo_score.toFixed(1)}</strong><em className={i.seo_delta>=0?"positive":"negative"}>{i.seo_delta>=0?"+":""}{i.seo_delta.toFixed(1)}</em></div><div><span>AI-search</span><strong>{i.previous_ai_visibility_score.toFixed(1)} to {i.current_ai_visibility_score.toFixed(1)}</strong><em className={i.ai_visibility_delta>=0?"positive":"negative"}>{i.ai_visibility_delta>=0?"+":""}{i.ai_visibility_delta.toFixed(1)}</em></div></div><div className="mini-stats"><span><strong>{i.issues_resolved}</strong> resolved</span><span><strong>{i.issues_introduced}</strong> introduced</span><span><strong>{i.recommendations_applied}</strong> credited fixes</span></div><p>{i.is_comparable?i.summary:i.incomparable_reason}</p></article>)}</div>:<div className="empty-inline">Run a second scan after making changes, then compare the scans to build evidence of improvement.</div>}</section></div>}

function NotificationsPanel({notifications,activities,onReadAll}:{notifications:Notification[];activities:Activity[];onReadAll:()=>void}) { return <div className="workspace-grid two-col"><section className="panel"><div className="panel-head"><div><p className="eyebrow">NOTIFICATIONS</p><h3>Workspace alerts</h3></div>{notifications.some(n=>!n.is_read)&&<button className="button secondary" onClick={onReadAll}>Mark all read</button>}</div>{notifications.length?<div className="stack-list">{notifications.map(n=><div className={`list-row ${n.is_read?"read":"unread"}`} key={n.id}><div><strong>{n.title}</strong><p>{n.message}</p></div><Badge tone={n.level}>{pretty(n.level)}</Badge></div>)}</div>:<div className="empty-inline">No notifications yet.</div>}</section><section className="panel"><div className="panel-head"><div><p className="eyebrow">ACTIVITY</p><h3>Audit history</h3></div></div>{activities.length?<div className="activity-list">{activities.map(a=><div key={a.id}><span className="activity-dot"></span><div><strong>{pretty(a.action)}</strong><p>{a.description}</p></div><time>{dateText(a.created_at)}</time></div>)}</div>:<div className="empty-inline">No activity recorded yet.</div>}</section></div>}

function SettingsPanel({business,profileForm,setProfileForm,onSave,capabilities,working}:{business:Business;profileForm:{target_audience:string;brand_voice:string;brand_tone:string;keywords:string;products:string;services:string};setProfileForm:(v:{target_audience:string;brand_voice:string;brand_tone:string;keywords:string;products:string;services:string})=>void;onSave:(e:FormEvent)=>void;capabilities:Capabilities|null;working:boolean}) { return <div className="workspace-grid two-col"><form className="panel form-grid" onSubmit={onSave}><div><p className="eyebrow">BUSINESS PROFILE</p><h3>{business.name}</h3><p className="helper">This context is used to ground content generation and assistant answers.</p></div><label>Target audience<textarea value={profileForm.target_audience} onChange={e=>setProfileForm({...profileForm,target_audience:e.target.value})}/></label><label>Products<input value={profileForm.products} onChange={e=>setProfileForm({...profileForm,products:e.target.value})} placeholder="comma separated"/></label><label>Services<input value={profileForm.services} onChange={e=>setProfileForm({...profileForm,services:e.target.value})} placeholder="comma separated"/></label><label>Target keywords<input value={profileForm.keywords} onChange={e=>setProfileForm({...profileForm,keywords:e.target.value})} placeholder="comma separated"/></label><label>Brand voice<input value={profileForm.brand_voice} onChange={e=>setProfileForm({...profileForm,brand_voice:e.target.value})}/></label><label>Brand tone<input value={profileForm.brand_tone} onChange={e=>setProfileForm({...profileForm,brand_tone:e.target.value})}/></label><button className="button" disabled={working}>{working?"Saving…":"Save profile"}</button></form><section className="panel"><div><p className="eyebrow">CAPABILITIES</p><h3>What is live on this installation</h3></div><div className="capability-list"><div><span>Database</span><Badge tone="live">{capabilities?.database??"unknown"}</Badge></div><div><span>AI</span><Badge tone={capabilities?.ai.enabled?"live":"demo"}>{capabilities?.ai.enabled?capabilities.ai.model??"live":"demo mode"}</Badge></div><div><span>Scheduler</span><Badge tone={capabilities?.scheduler.enabled?"live":"demo"}>{capabilities?.scheduler.enabled?"enabled":"disabled"}</Badge></div>{Object.entries(capabilities?.connectors??{}).map(([name,cfg])=><div key={name}><span>{pretty(name)} publishing</span><Badge tone={cfg.mode}>{pretty(cfg.mode)}</Badge></div>)}</div><div className="helper">The application never hides demo data or claims an unavailable external integration is live.</div></section></div>}

function ScheduleModal({content,connectionId,onClose,onSchedule}:{content:Content|null;connectionId:string;onClose:()=>void;onSchedule:(contentId:string,connectionId:string,when:string)=>void}) { const [when,setWhen]=useState(""); return <Modal title="Schedule publication" onClose={onClose}><div className="form-grid"><div className="info-box"><strong>{content?.title??"Draft"}</strong><p>Choose a future local time. AURA stores the timestamp in UTC while preserving the user's timezone for display.</p></div><label>Date and time<input type="datetime-local" value={when} onChange={e=>setWhen(e.target.value)} required/></label><div className="modal-actions"><button className="button secondary" onClick={onClose}>Cancel</button><button className="button" disabled={!content||!when} onClick={()=>content&&onSchedule(content.id,connectionId,when)}>Schedule</button></div></div></Modal> }
